import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:introduction_screen/introduction_screen.dart';import 'package:zan/Core/Utils/Extensions/int_extension.dart';class AppConstants {  static DotsDecorator get dotsDecoration {    return DotsDecorator(      size: Size(8.w, 8.h),      activeSize: Size(24.w, 8.h),      color: Colors.white54,      activeColor: Colors.white,      spacing: EdgeInsets.symmetric(horizontal: 4.w),      activeShape: RoundedRectangleBorder(        borderRadius: BorderRadius.circular(25.0),      ),    );  }  static SliverGridDelegate get gridDelegate =>      SliverGridDelegateWithFixedCrossAxisCount(        crossAxisCount: 4.crossAxisCount,        mainAxisSpacing: 21.h,        crossAxisSpacing: 21.w,        childAspectRatio: 156.w / 225.h,      );}